    },
    {
      "check": "fx_quote_expiry_execution_risk",
      "severity": "note",
      "detail": "The quote expires at 2026-11-02T14:15:00Z and now is 2026-11-02T14:00:00Z. The FX conversion must execute before expiry; otherwise the retry lacks the 28,000 USD purchase."
